$ErrorActionPreference='Stop'
Add-Type -AssemblyName System.IO.Compression.FileSystem
$zip=Join-Path $env:USERPROFILE 'Downloads\TGCV_MT4_energy_public-dataset_v2.zip'
$out=Join-Path $env:USERPROFILE 'Downloads\TGCV_MT4_5_PTAU_POTENTIAL_ANNUAL_COLLISION_SUMMARY_001.txt'
$expected='691F950A314015A7DE9D4CBABCC177846D74ABF7036B6A89E192B152A88E6D30';$sha=(Get-FileHash $zip -Algorithm SHA256).Hash.ToUpperInvariant();$md5=(Get-FileHash $zip -Algorithm MD5).Hash.ToUpperInvariant();if($sha-ne$expected){throw 'ZIP SHA256 mismatch'}
function P([string]$l){$l -split ',(?=(?:[^\"]*\"[^\"]*\")*[^\"]*$)',10};function C([string]$s){if($null-eq$s){return ''};$s.Trim().Trim('"')}
$rows=@();$z=[IO.Compression.ZipFile]::OpenRead($zip);try{foreach($e in $z.Entries|Where-Object{$_.FullName-match'/Technologies/[^/]+\.csv$'}){$r=[IO.StreamReader]::new($e.Open());try{while(($l=$r.ReadLine())-ne$null){$x=P $l;if($x.Count-lt 10){continue};$rows+=,[pscustomobject]@{Country=C $x[0];Technology=[IO.Path]::GetFileNameWithoutExtension($e.Name);Parameter=C $x[2];Year=C $x[3];Value=C $x[5];Reference=C $x[7];Note=C $x[9]}}}finally{$r.Dispose()}}}finally{$z.Dispose()}
$core=@('Fuel_efficiency','LF_min','LF_max','Peak_contr','Ramp_rate','Resource');$cells=$rows|Group-Object Country,Technology,Year;$complete=@();foreach($g in $cells){$d=@{};foreach($r in $g.Group){$d[$r.Parameter]=$r};$ok=$true;foreach($p in $core){if(!$d.ContainsKey($p)-or[string]::IsNullOrWhiteSpace($d[$p].Value)){$ok=$false;break}};if($ok){$complete+=[pscustomobject]@{Key=$g.Name;Country=$g.Group[0].Country;Technology=$g.Group[0].Technology;Year=$g.Group[0].Year;Rows=$d}}}
$coll=@();foreach($g in ($complete|Group-Object Country,Year)){ $sig=$g.Group|ForEach-Object{($_.Rows[$core]|ForEach-Object{$_.Value})-join'|'}|Group-Object;if(($sig|Where-Object Count -gt 1).Count -gt 0){foreach($sg in $sig|Where-Object Count -gt 1){$coll+=$g.Group|Where-Object{(($_.Rows[$core]|ForEach-Object{$_.Value})-join'|')-eq$sg.Name}}}}
$details=@();foreach($c in $coll){$pa=$rows|Where-Object{$_.Country-eq$c.Country -and $_.Technology-eq$c.Technology -and $_.Year-eq$c.Year -and $_.Parameter-eq'Potential_annual'}|Select-Object -First 1;if($pa){$flag='CLEAN_OR_UNCLASSIFIED';$txt=($pa.Reference+' '+$pa.Note);if($txt-match'(?i)201\d|202\d|based on|estimate|estimated|historical|retrospective|corrected|adjusted|maximum historical|planned|future'){$flag='TEMPORAL_REVIEW_REQUIRED'};$details+=[pscustomobject]@{Country=$c.Country;Year=$c.Year;Technology=$c.Technology;Potential_annual=$pa.Value;Reference=$pa.Reference;Note=$pa.Note;TemporalFlag=$flag}}else{$details+=[pscustomobject]@{Country=$c.Country;Year=$c.Year;Technology=$c.Technology;Potential_annual='';Reference='';Note='MISSING';TemporalFlag='MISSING'}}}
$lines=@('TGCV MT4-5 - Potential_annual collision auditor 001',"SHA256=$sha","MD5=$md5","CORE6_COLLISION_CELLS=$($coll.Count)","POTENTIAL_ANNUAL_COLLISION_RECORDS=$($details.Count)",'','PURPOSE=Determine whether Potential_annual is an independently admissibility-relevant dimension in CORE_6 collision groups without promoting it automatically into P_tau.','RULE=Temporal or semantic contamination excludes automatic promotion; no outcome/realization variables may define accessibility.','');if($details.Count){$lines+=($details|ForEach-Object{"$($_.Country)|$($_.Year)|$($_.Technology)|Potential_annual=$($_.Potential_annual)|TemporalFlag=$($_.TemporalFlag)|Reference=$($_.Reference)|Note=$($_.Note)"})}else{$lines+='RESULT=No Potential_annual records found in CORE6 collision groups.'};$review=($details|Where-Object TemporalFlag-eq'TEMPORAL_REVIEW_REQUIRED').Count;$clean=($details|Where-Object TemporalFlag-eq'CLEAN_OR_UNCLASSIFIED').Count;$lines+=@('','TEMPORAL_REVIEW_REQUIRED='+$review,'CLEAN_OR_UNCLASSIFIED='+$clean,'INTERPRETATION=This is a diagnostic. A clean Potential_annual difference may justify a targeted semantic review, but does not establish P_tau sufficiency or permit automatic promotion.','SUFFICIENT_FOR_P_tau=UNDETERMINED','STATUS=ANALYTICAL DIAGNOSTIC - NOT A FINAL MT4-5 GATE DECISION');[IO.File]::WriteAllLines($out,$lines);Write-Output "OUTPUT=$out";Write-Output "CORE6_COLLISION_CELLS=$($coll.Count)";Write-Output "POTENTIAL_ANNUAL_COLLISION_RECORDS=$($details.Count)";Write-Output "TEMPORAL_REVIEW_REQUIRED=$review";Write-Output "CLEAN_OR_UNCLASSIFIED=$clean";Write-Output 'SUFFICIENT_FOR_P_tau=UNDETERMINED';Write-Output 'STATUS=ANALYTICAL DIAGNOSTIC - NOT A FINAL MT4-5 GATE DECISION'